class Menu;
class camera;

void *operator new(unsigned int, unsigned int, const char *, int);

class MenuEntry {
    unsigned int flags;
public:
    MenuEntry() { flags = 3; }
    virtual ~MenuEntry() {}
    virtual void Disable();
};

class MenuEntryLabel : public MenuEntry {
protected:
    const char *label;
public:
    MenuEntryLabel(const char *t) { label = t; }
    virtual ~MenuEntryLabel() {}
};

class MenuEntryTitle : public MenuEntryLabel {
public:
    MenuEntryTitle(char *t) : MenuEntryLabel(t) { Disable(); }
    virtual ~MenuEntryTitle() {}
    virtual void Enable() { Disable(); }
    virtual void Disable() { MenuEntry::Disable(); }
};

class camMenuObj;

class ChangeCamMenuEntryFunction : public MenuEntryLabel {
    camMenuObj *parent;
public:
    ChangeCamMenuEntryFunction(char *t, camMenuObj *p) : MenuEntryLabel(t) { parent = p; }
    virtual ~ChangeCamMenuEntryFunction() {}
};

class DeleteCamMenuEntryFunction : public MenuEntryLabel {
    camMenuObj *parent;
public:
    DeleteCamMenuEntryFunction(char *t, camMenuObj *p) : MenuEntryLabel(t) { parent = p; }
    virtual ~DeleteCamMenuEntryFunction() {}
};

class Submenu : public MenuEntryLabel {
    Menu *menuopen;
    Menu *parent;
    void *system;
public:
    Submenu(char *text, Menu *p) : MenuEntryLabel(text) { menuopen = p; parent = 0; system = 0; }
    virtual ~Submenu() {}
};

class Menu {
public:
    Menu(Menu *);
    void AddEntry(MenuEntry *);
};

class camMenuObj {
public:
    camMenuObj(char *name, Menu *menu_parent, camera *cam);
    bool deleted;
    bool po_changed;
private:
    camera *p_dbg_cam;
    MenuEntryTitle *cam_title;
    ChangeCamMenuEntryFunction *ent1;
    DeleteCamMenuEntryFunction *ent2;
    Menu *inner_menu;
    Submenu *cam_submenu;
    Menu *parent;
};

#define NEW new(0, "KS/SRC/ks/camera_tool.cpp", 0)

camMenuObj::camMenuObj(char *name, Menu *menu_parent, camera *cam)
{
	deleted = false;
	po_changed = false;
	p_dbg_cam = cam;
	parent = menu_parent;
	cam_title= NEW MenuEntryTitle(name);
	ent1 = NEW ChangeCamMenuEntryFunction( "Change PO", this );
	ent2 = NEW DeleteCamMenuEntryFunction("Delete Camera", this );
	inner_menu = NEW Menu(menu_parent);
	inner_menu->AddEntry(cam_title);
	inner_menu->AddEntry(ent1);
	inner_menu->AddEntry(ent2);
	cam_submenu = NEW Submenu(name, inner_menu);
	menu_parent->AddEntry(cam_submenu);
}
